ALTER TABLE posts ADD COLUMN language TEXT NOT NULL DEFAULT 'zh-CN';
ALTER TABLE posts ADD COLUMN translationKey TEXT;
ALTER TABLE posts ADD COLUMN category TEXT NOT NULL DEFAULT '';
CREATE UNIQUE INDEX posts_translation_language ON posts(translationKey,language) WHERE translationKey IS NOT NULL AND deletedAt IS NULL;
CREATE INDEX posts_language_public ON posts(language,draft,hidden,deletedAt,publishedAt);
CREATE INDEX posts_category_public ON posts(category,draft,hidden,deletedAt,publishedAt);
CREATE INDEX posts_series_public ON posts(series,draft,hidden,deletedAt,publishedAt);
CREATE TABLE writing_assets (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('template','snippet')), name TEXT NOT NULL, content TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE preview_shares (id TEXT PRIMARY KEY, tokenHash TEXT NOT NULL UNIQUE, draftId TEXT NOT NULL REFERENCES post_drafts(id) ON DELETE CASCADE, data TEXT NOT NULL, createdAt TEXT NOT NULL, expiresAt TEXT NOT NULL);
CREATE INDEX preview_shares_expiry ON preview_shares(expiresAt);
CREATE TABLE admin_passkeys (id TEXT PRIMARY KEY, publicKey BLOB NOT NULL, counter INTEGER NOT NULL, transports TEXT NOT NULL, name TEXT NOT NULL, createdAt TEXT NOT NULL, lastUsedAt TEXT);
CREATE TABLE auth_challenges (id TEXT PRIMARY KEY, challenge TEXT NOT NULL, purpose TEXT NOT NULL, sessionId TEXT REFERENCES admin_sessions(id) ON DELETE CASCADE, expiresAt INTEGER NOT NULL);
ALTER TABLE admin_sessions ADD COLUMN userAgent TEXT NOT NULL DEFAULT '';
ALTER TABLE admin_sessions ADD COLUMN lastSeenAt TEXT;
ALTER TABLE admin_sessions ADD COLUMN authMethod TEXT NOT NULL DEFAULT 'password';
ALTER TABLE admin_sessions ADD COLUMN verifiedAt INTEGER NOT NULL DEFAULT 0;
CREATE TABLE post_topics (postId INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE, tag TEXT NOT NULL, PRIMARY KEY(postId,tag));
CREATE INDEX post_topics_tag ON post_topics(tag,postId);
INSERT OR IGNORE INTO post_topics SELECT p.id,t.value FROM posts p,json_each(p.tags) t;
CREATE TRIGGER post_topics_insert AFTER INSERT ON posts BEGIN INSERT OR IGNORE INTO post_topics SELECT new.id,value FROM json_each(new.tags); END;
CREATE TRIGGER post_topics_update AFTER UPDATE OF tags ON posts BEGIN DELETE FROM post_topics WHERE postId=new.id; INSERT OR IGNORE INTO post_topics SELECT new.id,value FROM json_each(new.tags); END;
